=head2 Google::Cloud::Dialogflow::Cx::V3beta1::Session::StreamingDetectIntentRequest

The top-level message sent by the client to the
[Sessions.StreamingDetectIntent][google.cloud.dialogflow.cx.v3beta1.Sessions.StreamingDetectIntent]
method.

Multiple request messages should be sent in order:

1.  The first message must contain
    [session][google.cloud.dialogflow.cx.v3beta1.StreamingDetectIntentRequest.session],
    [query_input][google.cloud.dialogflow.cx.v3beta1.StreamingDetectIntentRequest.query_input]
    plus optionally
    [query_params][google.cloud.dialogflow.cx.v3beta1.StreamingDetectIntentRequest.query_params].
    If the client wants to receive an audio response, it should also contain
    [output_audio_config][google.cloud.dialogflow.cx.v3beta1.StreamingDetectIntentRequest.output_audio_config].

2.  If
[query_input][google.cloud.dialogflow.cx.v3beta1.StreamingDetectIntentRequest.query_input]
was set to
    [query_input.audio.config][google.cloud.dialogflow.cx.v3beta1.AudioInput.config],
    all subsequent messages must contain
    [query_input.audio.audio][google.cloud.dialogflow.cx.v3beta1.AudioInput.audio]
    to continue with Speech recognition. If you decide to rather detect an
    intent from text input after you already started Speech recognition,
    please send a message with
    [query_input.text][google.cloud.dialogflow.cx.v3beta1.QueryInput.text].

    However, note that:

    * Dialogflow will bill you for the audio duration so far.
    * Dialogflow discards all Speech recognition results in favor of the
      input text.
    * Dialogflow will use the language code from the first message.

After you sent all input, you must half-close or abort the request stream.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->session() >> / C<< $msg->session($value) >>

Type: C<String>

The name of the session this query is sent to.
Format:
`projects/<ProjectID>/locations/<LocationID>/agents/<AgentID>/sessions/<SessionID>`
or
`projects/<ProjectID>/locations/<LocationID>/agents/<AgentID>/environments/<EnvironmentID>/sessions/<SessionID>`.
If `Environment ID` is not specified, we assume default 'draft'
 environment.
 It's up to the API caller to choose an appropriate `Session ID`. It can be
 a random number or some type of session identifiers (preferably hashed).
 The length of the `Session ID` must not exceed 36 characters.
 Note: session must be set in the first request.

 For more information, see the [sessions
 guide](https://cloud.google.com/dialogflow/cx/docs/concept/session).

 Note: Always use agent versions for production traffic.
 See [Versions and
 environments](https://cloud.google.com/dialogflow/cx/docs/concept/version).

=item * C<< $msg->query_params() >> / C<< $msg->query_params($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::Cx::V3beta1::Session::QueryParameters>)

The parameters of this query.

=item * C<< $msg->query_input() >> / C<< $msg->query_input($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::Cx::V3beta1::Session::QueryInput>)

Required. The input specification.

=item * C<< $msg->output_audio_config() >> / C<< $msg->output_audio_config($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::Cx::V3beta1::AudioConfig::OutputAudioConfig>)

Instructs the speech synthesizer how to generate the output audio.

=item * C<< $msg->enable_partial_response() >> / C<< $msg->enable_partial_response($value) >>

Type: C<Bool>

Enable partial detect intent response. If this flag is not enabled,
response stream still contains only one final `DetectIntentResponse` even
if some `Fulfillment`s in the agent have been configured to return partial
responses.

=item * C<< $msg->enable_debugging_info() >> / C<< $msg->enable_debugging_info($value) >>

Type: C<Bool>

If true, `StreamingDetectIntentResponse.debugging_info` will get populated.

=item * C<< $msg->response_view() >> / C<< $msg->response_view($value) >>

Type: C<Enum> (L<Google::Cloud::Dialogflow::Cx::V3beta1::DetectIntentResponseView>)

Optional. Specifies which fields in the
[QueryResult][google.cloud.dialogflow.cx.v3beta1.QueryResult] to return. If
not set, the default is DETECT_INTENT_RESPONSE_VIEW_FULL.

=back

