Type: C<String>

The language that was triggered during intent detection.
See [Language
Support](https://cloud.google.com/dialogflow/cx/docs/reference/language)
for a list of the currently supported language codes.

=item * C<< $msg->parameters() >> / C<< $msg->parameters($value) >>

Type: C<Message> (L<Google::Protobuf::Struct::Struct>)

The collected [session
parameters][google.cloud.dialogflow.cx.v3beta1.SessionInfo.parameters].

Depending on your protocol or client library language, this is a
map, associative array, symbol table, dictionary, or JSON object
composed of a collection of (MapKey, MapValue) pairs:

* MapKey type: string
* MapKey value: parameter name
* MapValue type: If parameter's entity type is a composite entity then use
map, otherwise, depending on the parameter value type, it could be one of
string, number, boolean, null, list or map.
* MapValue value: If parameter's entity type is a composite entity then use
map from composite entity property names to property values, otherwise,
use parameter value.

=item * C<< $msg->response_messages() >> / C<< $msg->response_messages($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::Cx::V3beta1::ResponseMessage::ResponseMessage>)

The list of rich messages returned to the client. Responses vary from
simple text messages to more sophisticated, structured payloads used
to drive complex logic.

=item * C<< $msg->webhook_ids() >> / C<< $msg->webhook_ids($value) >>

Type: C<String>

The list of webhook ids in the order of call sequence.

=item * C<< $msg->webhook_display_names() >> / C<< $msg->webhook_display_names($value) >>

Type: C<String>

The list of webhook display names in the order of call sequence.

=item * C<< $msg->webhook_latencies() >> / C<< $msg->webhook_latencies($value) >>

Type: C<Message> (L<Google::Protobuf::Duration::Duration>)

The list of webhook latencies in the order of call sequence.

=item * C<< $msg->webhook_tags() >> / C<< $msg->webhook_tags($value) >>

Type: C<String>

The list of webhook tags in the order of call sequence.

=item * C<< $msg->webhook_statuses() >> / C<< $msg->webhook_statuses($value) >>

Type: C<Message> (L<Google::Rpc::Status::Status>)

The list of webhook call status in the order of call sequence.

=item * C<< $msg->webhook_payloads() >> / C<< $msg->webhook_payloads($value) >>

Type: C<Message> (L<Google::Protobuf::Struct::Struct>)

The list of webhook payload in
[WebhookResponse.payload][google.cloud.dialogflow.cx.v3beta1.WebhookResponse.payload],
in the order of call sequence. If some webhook call fails or doesn't return
any payload, an empty `Struct` would be used instead.

=item * C<< $msg->current_page() >> / C<< $msg->current_page($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::Cx::V3beta1::Page::Page>)

The current [Page][google.cloud.dialogflow.cx.v3beta1.Page]. Some, not all
fields are filled in this message, including but not limited to `name` and
`display_name`.

=item * C<< $msg->current_flow() >> / C<< $msg->current_flow($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::Cx::V3beta1::Flow::Flow>)

The current [Flow][google.cloud.dialogflow.cx.v3beta1.Flow]. Some, not all
fields are filled in this message, including but not limited to `name` and
`display_name`.

=item * C<< $msg->intent() >> / C<< $msg->intent($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::Cx::V3beta1::Intent::Intent>)

The [Intent][google.cloud.dialogflow.cx.v3beta1.Intent] that matched the
conversational query. Some, not all fields are filled in this message,
including but not limited to: `name` and `display_name`. This field is
deprecated, please use
[QueryResult.match][google.cloud.dialogflow.cx.v3beta1.QueryResult.match]
instead.

=item * C<< $msg->intent_detection_confidence() >> / C<< $msg->intent_detection_confidence($value) >>

Type: C<Float>

The intent detection confidence. Values range from 0.0 (completely
uncertain) to 1.0 (completely certain).
This value is for informational purpose only and is only used to
help match the best intent within the classification threshold.
This value may change for the same end-user expression at any time due to a
model retraining or change in implementation.
This field is deprecated, please use
[QueryResult.match][google.cloud.dialogflow.cx.v3beta1.QueryResult.match]
instead.

=item * C<< $msg->match() >> / C<< $msg->match($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::Cx::V3beta1::Session::Match>)

Intent match result, could be an intent or an event.

=item * C<< $msg->diagnostic_info() >> / C<< $msg->diagnostic_info($value) >>

Type: C<Message> (L<Google::Protobuf::Struct::Struct>)

The free-form diagnostic info. For example, this field could contain
webhook call latency. The fields of this data can change without notice,
so you should not write code that depends on its structure.

One of the fields is called "Alternative Matched Intents", which may
aid with debugging. The following describes these intent results:

- The list is empty if no intent was matched to end-user input.
- Only intents that are referenced in the currently active flow are
  included.
- The matched intent is included.
- Other intents that could have matched end-user input, but did not match
  because they are referenced by intent routes that are out of
  [scope](https://cloud.google.com/dialogflow/cx/docs/concept/handler#scope),
  are included.
- Other intents referenced by intent routes in scope that matched end-user
  input, but had a lower confidence score.

=item * C<< $msg->generative_info() >> / C<< $msg->generative_info($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::Cx::V3beta1::Session::GenerativeInfo>)

The information of a query if handled by generative agent resources.

=item * C<< $msg->sentiment_analysis_result() >> / C<< $msg->sentiment_analysis_result($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::Cx::V3beta1::Session::SentimentAnalysisResult>)

The sentiment analyss result, which depends on
[`analyze_query_text_sentiment`]
[google.cloud.dialogflow.cx.v3beta1.QueryParameters.analyze_query_text_sentiment],
specified in the request.

=item * C<< $msg->advanced_settings() >> / C<< $msg->advanced_settings($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::Cx::V3beta1::AdvancedSettings::AdvancedSettings>)

Returns the current advanced settings including IVR settings. Even though
the operations configured by these settings are performed by Dialogflow,
the client may need to perform special logic at the moment. For example, if
Dialogflow exports audio to Google Cloud Storage, then the client may need
to wait for the resulting object to appear in the bucket before proceeding.

=item * C<< $msg->allow_answer_feedback() >> / C<< $msg->allow_answer_feedback($value) >>

Type: C<Bool>

Indicates whether the Thumbs up/Thumbs down rating controls are need to be
shown for the response in the Dialogflow Messenger widget.

=item * C<< $msg->data_store_connection_signals() >> / C<< $msg->data_store_connection_signals($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::Cx::V3beta1::DataStoreConnection::DataStoreConnectionSignals>)

Optional. Data store connection feature output signals.
Filled only when data stores are involved in serving the query.

=item * C<< $msg->trace_blocks() >> / C<< $msg->trace_blocks($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::Cx::V3beta1::Trace::TraceBlock>)

Optional. Contains the sequence of trace blocks from the current
conversation turn. Trace blocks are ordered chronologically and contain
detailed traces of runtime behavior such as tool calls, LLM calls, flow and
playbook invocations, agent utterances and user utterances.

=back

